import * as React from "react";
import { type Slot } from "@puckeditor/core";
import "./columns.css";

export interface ColumnsProps {
  distribution: "1:1" | "1:1:1" | "2:1" | "1:2" | "1:1:1:1";
  gap: "tight" | "regular" | "wide";
  valign: "top" | "center" | "stretch";
  tone: "none" | "light";
  col1: Slot;
  col2: Slot;
  col3: Slot;
  col4: Slot;
}

const TEMPLATES: Record<ColumnsProps["distribution"], { count: number; template: string }> = {
  "1:1": { count: 2, template: "1fr 1fr" },
  "2:1": { count: 2, template: "1.5fr 1fr" },
  "1:2": { count: 2, template: "1fr 1.5fr" },
  "1:1:1": { count: 3, template: "1fr 1fr 1fr" },
  "1:1:1:1": { count: 4, template: "1fr 1fr 1fr 1fr" },
};

function SlotPlaceholder({ label }: { label: string }) {
  return <div className="p1-columns__placeholder">{label}</div>;
}

/** Render a slot safely — a Puck SlotComponent in the editor or a static placeholder. */
function renderSlot(slot: unknown, label: string) {
  if (typeof slot === "function") {
    const Comp = slot as React.ComponentType;
    return <Comp />;
  }
  return <SlotPlaceholder label={label} />;
}

export function ColumnsRender({ distribution, gap, valign, tone, col1, col2, col3, col4 }: ColumnsProps) {
  const { count, template } = TEMPLATES[distribution ?? "1:1"];
  const slots = [col1, col2, col3, col4].slice(0, count);
  return (
    <div className="p1-columns" data-tone={tone}>
      <div
        className="p1-columns__grid"
        data-gap={gap}
        data-valign={valign}
        style={{ gridTemplateColumns: template }}
      >
        {slots.map((slot, i) => (
          <div key={i} className="p1-columns__col">
            {renderSlot(slot, `Column ${i + 1} — drop blocks here`)}
          </div>
        ))}
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { ColumnsRender, type ColumnsProps } from "./columns";
export type { ColumnsProps };

export const ColumnsBlock: ComponentConfig<ColumnsProps> = {
  fields: {
    distribution: {
      type: "select" as const,
      options: [
        { label: "Two — even", value: "1:1" },
        { label: "Two — left wide", value: "2:1" },
        { label: "Two — right wide", value: "1:2" },
        { label: "Three", value: "1:1:1" },
        { label: "Four", value: "1:1:1:1" },
      ],
    },
    gap: {
      type: "select" as const,
      options: [
        { label: "Tight", value: "tight" },
        { label: "Regular", value: "regular" },
        { label: "Wide", value: "wide" },
      ],
    },
    valign: {
      type: "select" as const,
      options: [
        { label: "Top", value: "top" },
        { label: "Center", value: "center" },
        { label: "Stretch", value: "stretch" },
      ],
    },
    tone: {
      type: "radio" as const,
      options: [
        { label: "None", value: "none" },
        { label: "Light", value: "light" },
      ],
    },
    col1: { type: "slot" as const },
    col2: { type: "slot" as const },
    col3: { type: "slot" as const },
    col4: { type: "slot" as const },
  },
  defaultProps: {
    distribution: "1:1",
    gap: "regular",
    valign: "top",
    tone: "none",
    col1: [],
    col2: [],
    col3: [],
    col4: [],
  },
  render: ColumnsRender as unknown as ComponentConfig<ColumnsProps>["render"],
};

export const meta = defineMeta({
  title: 'Columns',
  description: 'Drag-and-drop layout grid of 2–4 columns with configurable ratio, gap, and vertical alignment; use as a layout wrapper for other blocks.',
  categories: ["layout"],
  published: true,
});

.p1-columns {
  padding-block: var(--p1-space-lg);
  padding-inline: var(--p1-space-lg);
}

.p1-columns[data-tone="light"] {
  background-color: var(--p1-surface-subtle);
}

.p1-columns__grid {
  display: grid;
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
  /* gridTemplateColumns is set via inline style from the distribution prop */
}

.p1-columns__grid[data-gap="tight"]   { gap: var(--p1-space-md); }
.p1-columns__grid[data-gap="regular"] { gap: var(--p1-space-lg); }
.p1-columns__grid[data-gap="wide"]    { gap: var(--p1-space-xl); }

.p1-columns__grid[data-valign="top"]     { align-items: start; }
.p1-columns__grid[data-valign="center"]  { align-items: center; }
.p1-columns__grid[data-valign="stretch"] { align-items: stretch; }

.p1-columns__col { min-inline-size: 0; }

.p1-columns__placeholder {
  border: 1px dashed var(--p1-border);
  border-radius: var(--p1-radius-card);
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  padding: var(--p1-space-lg);
  text-align: center;
}

@media (width < 48rem) {
  .p1-columns__grid { grid-template-columns: 1fr !important; }
}

